@* Displays a single product as a card with image, name, price, rating, stock badge, and add-to-cart *@

<div class="product-card" @onclick="HandleCardClick" style="border:1px solid #ddd; border-radius:8px; padding:0; cursor:pointer; display:flex; flex-direction:column; overflow:hidden;">
    <div style="background:#e0e0e0; height:180px; display:flex; align-items:center; justify-content:center; color:#888; font-size:0.9rem;">
        @Product.Name
    </div>
    <div style="padding:12px; flex:1; display:flex; flex-direction:column; gap:6px;">
        <h4 style="margin:0;">@Product.Name</h4>
        <span style="font-size:1.1rem; font-weight:bold; color:#2a7ae2;">@Product.Price.ToString("C")</span>
        <span aria-label="@($"Rating: {Product.Rating:F1} out of 5")">@GetStarDisplay(Product.Rating)</span>
        @if (!Product.InStock)
        {
            <span style="display:inline-block; background:#dc3545; color:#fff; padding:2px 8px; border-radius:4px; font-size:0.8rem; width:fit-content;">Out of Stock</span>
        }
        <button disabled="@(!Product.InStock)" @onclick="HandleAddToCart" @onclick:stopPropagation="true"
                style="margin-top:auto; padding:8px 12px; border:none; border-radius:4px; cursor:pointer;
                       background:@(Product.InStock ? "#2a7ae2" : "#ccc"); color:#fff;">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarDisplay(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

@* Renders a responsive grid of ProductCard components *@

<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(240px, 1fr)); gap:20px;">
    @foreach (var product in Products)
    {
        <ProductCard Product="product"
                     OnSelected="OnProductSelected"
                     OnAddToCart="OnAddToCart" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@* Sidebar filter panel: category checkboxes, price range, stock toggle, apply/clear buttons *@

<div style="padding:16px; border:1px solid #ddd; border-radius:8px;">
    <h3 style="margin-top:0;">Filters</h3>

    <fieldset style="border:none; padding:0; margin:0 0 16px 0;">
        <legend style="font-weight:bold; margin-bottom:8px;">Categories</legend>
        @foreach (var category in Categories)
        {
            <label style="display:block; margin-bottom:4px; cursor:pointer;">
                <input type="checkbox" checked="@_selectedCategories.Contains(category)"
                       @onchange="() => ToggleCategory(category)" />
                @category
            </label>
        }
    </fieldset>

    <div style="margin-bottom:16px;">
        <label style="font-weight:bold; display:block; margin-bottom:4px;">Min Price</label>
        <input type="number" min="0" step="0.01" @bind="_minPrice"
               style="width:100%; padding:6px; box-sizing:border-box;" />
    </div>

    <div style="margin-bottom:16px;">
        <label style="font-weight:bold; display:block; margin-bottom:4px;">Max Price</label>
        <input type="number" min="0" step="0.01" @bind="_maxPrice"
               style="width:100%; padding:6px; box-sizing:border-box;" />
    </div>

    <label style="display:block; margin-bottom:16px; cursor:pointer;">
        <input type="checkbox" @bind="_inStockOnly" />
        <strong>In Stock Only</strong>
    </label>

    <div style="display:flex; gap:8px;">
        <button @onclick="ApplyFilters"
                style="flex:1; padding:8px; background:#2a7ae2; color:#fff; border:none; border-radius:4px; cursor:pointer;">
            Apply Filters
        </button>
        <button @onclick="ClearFilters"
                style="flex:1; padding:8px; background:#6c757d; color:#fff; border:none; border-radius:4px; cursor:pointer;">
            Clear Filters
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private HashSet<string> _selectedCategories = [];
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private void ToggleCategory(string category)
    {
        if (!_selectedCategories.Remove(category))
        {
            _selectedCategories.Add(category);
        }
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }
}

@* Toolbar with sort dropdown and result count label *@

<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; flex-wrap:wrap; gap:8px;">
    <div>
        <label for="sort-select" style="font-weight:bold; margin-right:8px;">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged"
                style="padding:6px; border-radius:4px; border:1px solid #ccc;">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <span style="color:#666;">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <text>Showing @start–@end of @TotalCount products</text>
        }
        else
        {
            <text>No products found</text>
        }
    </span>
</div>

@code {
    [Parameter] public string SortBy { get; set; } = "price_asc";
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int Page { get; set; } = 1;
    [Parameter] public int PageSize { get; set; } = 12;
    [Parameter] public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@* Pagination: Previous, numbered page buttons, Next *@

@if (TotalPages > 1)
{
    <nav style="display:flex; justify-content:center; gap:4px; margin-top:24px; flex-wrap:wrap;" aria-label="Product pagination">
        <button disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)"
                style="@ButtonStyle(false)">
            Previous
        </button>

        @for (int i = 1; i <= TotalPages; i++)
        {
            var page = i;
            <button @onclick="() => GoToPage(page)"
                    style="@ButtonStyle(page == CurrentPage)">
                @page
            </button>
        }

        <button disabled="@(CurrentPage >= TotalPages)" @onclick="() => GoToPage(CurrentPage + 1)"
                style="@ButtonStyle(false)">
            Next
        </button>
    </nav>
}

@code {
    [Parameter] public int CurrentPage { get; set; } = 1;
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int PageSize { get; set; } = 12;
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 1;

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private string ButtonStyle(bool isActive) =>
        $"padding:6px 12px; border:1px solid #ccc; border-radius:4px; cursor:pointer; " +
        (isActive ? "background:#2a7ae2; color:#fff; font-weight:bold;" : "background:#fff; color:#333;");
}

