@* Pagination: Previous, numbered page buttons, Next *@

@if (TotalPages > 1)
{
    <nav style="display:flex; justify-content:center; gap:4px; margin-top:24px; flex-wrap:wrap;" aria-label="Product pagination">
        <button disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)"
                style="@ButtonStyle(false)">
            Previous
        </button>

        @for (int i = 1; i <= TotalPages; i++)
        {
            var page = i;
            <button @onclick="() => GoToPage(page)"
                    style="@ButtonStyle(page == CurrentPage)">
                @page
            </button>
        }

        <button disabled="@(CurrentPage >= TotalPages)" @onclick="() => GoToPage(CurrentPage + 1)"
                style="@ButtonStyle(false)">
            Next
        </button>
    </nav>
}

@code {
    [Parameter] public int CurrentPage { get; set; } = 1;
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int PageSize { get; set; } = 12;
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 1;

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private string ButtonStyle(bool isActive) =>
        $"padding:6px 12px; border:1px solid #ccc; border-radius:4px; cursor:pointer; " +
        (isActive ? "background:#2a7ae2; color:#fff; font-weight:bold;" : "background:#fff; color:#333;");
}

