arguments.file_text:
@page "/catalog"
@using sv_cbce119d97d84513a716c37d08ecd9a8.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_error is not null)
{
    <div style="padding:16px; background:#f8d7da; color:#842029; border-radius:8px; margin-bottom:16px;">
        <strong>Error:</strong> @_error
        <button @onclick="RetryLoad" style="margin-left:12px; padding:4px 12px; cursor:pointer;">Retry</button>
    </div>
}
else
{
    <div style="display:flex; gap:24px; align-items:flex-start;">
        @* Left sidebar — filters *@
        <aside style="width:25%; min-width:220px; flex-shrink:0;">
            <CatalogFilters Categories="_categories"
                            OnFilterApplied="HandleFilterApplied"
                            OnFilterCleared="HandleFilterCleared" />
        </aside>

        @* Main content area *@
        <main style="flex:1; min-width:0;">
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@(_result?.TotalCount ?? 0)"
                            Page="@_page"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            @if (_loading)
            {
                <div style="text-align:center; padding:48px; color:#666;">
                    <p>Loading products…</p>
                </div>
            }
            else if (_result is null || _result.Items.Count == 0)
            {
                <div style="text-align:center; padding:48px; color:#666;">
                    <p>No products match your filters.</p>
                </div>
            }
            else
            {
                <ProductGrid Products="_result.Items"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                <CatalogPagination CurrentPage="@_page"
                                   TotalCount="@_result.TotalCount"
                                   PageSize="@PageSize"
                                   OnPageChanged="HandlePageChanged" />
            }
        </main>
    </div>
}

@code {
    private const int PageSize = 12;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string> _categories = [];
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync(loadCategories: true);
    }

    private async Task LoadDataAsync(bool loadCategories = false)
    {
        try
        {
            _loading = true;
            _error = null;

            if (loadCategories)
            {
                _categories = await ProductService.GetCategoriesAsync();
            }

            _result = await ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _page = 1;
        await LoadDataAsync();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new(null, null, null, false);
        _page = 1;
        await LoadDataAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _page = 1;
        await LoadDataAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _page = page;
        await LoadDataAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Hook for cart integration
        return Task.CompletedTask;
    }

    private async Task RetryLoad()
    {
        await LoadDataAsync(loadCategories: _categories.Count == 0);
    }
}

